import type { z } from "zod";
import type { jobSchema } from "./schemas";

/** Validated fields managed through the CMS job-posting content type. */
export type JobData = z.output<typeof jobSchema>;
/** Employment terms supported by a job posting. */
export type EmploymentType = JobData["employmentType"];
/** Public job projection; active application forms are resolved only on detail reads. */
export type Job = JobData & {
	id: string;
	slug: string;
	createdAt: string;
	updatedAt: string;
	applicationFormSlug?: string;
};

/** Public filters. Closing dates remain open through the specified UTC day. */
export interface JobsFilters {
	department?: string;
	location?: string;
	employmentType?: EmploymentType;
	remote?: boolean;
	search?: string;
	limit?: number;
	offset?: number;
}

/** Available filter terms derived exclusively from published, unexpired jobs. */
export type JobTaxonomies = {
	departments: string[];
	locations: string[];
	employmentTypes: EmploymentType[];
};

/** A filtered page and the full public taxonomy catalog. */
export type JobsPage = {
	items: Job[];
	total: number;
	limit: number;
	offset: number;
	taxonomies: JobTaxonomies;
};

/** Existing CMS record fields needed for safe job projection and optimistic archival. */
export interface JobContentItem {
	id: string;
	slug: string;
	data: string;
	parsedData: Record<string, unknown>;
	createdAt: string;
	updatedAt: string;
}

import { z } from "zod";
import type { ContentTypeConfig } from "@btst/plugin-cms/api";

/** CMS fields shared by job management and the public job board. */
export const jobSchema = z.object({
	title: z.string().trim().min(1).max(200),
	department: z.string().trim().min(1).max(200),
	location: z.string().trim().min(1).max(200),
	employmentType: z
		.enum(["full-time", "part-time", "contract", "internship"])
		.meta({ fieldType: "select" }),
	remote: z.boolean().default(false),
	description: z.string().min(1).max(100_000).meta({ fieldType: "markdown" }),
	requirements: z.string().max(100_000).meta({ fieldType: "markdown" }),
	salary: z.string().max(500).optional(),
	closingDate: z.iso.date().nullable().optional().meta({ fieldType: "date" }),
	applicationFormId: z.string().max(200).optional(),
	status: z
		.enum(["draft", "published", "archived"])
		.default("draft")
		.meta({ fieldType: "select" }),
});

/** Content type registered on the existing CMS backend; creates no new models. */
export const JOB_BOARD_CONTENT_TYPE: ContentTypeConfig = {
	name: "Job Posting",
	slug: "job-posting",
	description: "Careers and job board postings",
	schema: jobSchema,
};

/** Canonical CMS content-type slug for job postings. */
export const JOB_BOARD_TYPE_SLUG = "job-posting" as const;

const optionalFilter = z.string().trim().max(200).optional();
/** Validated public filtering and pagination; publication controls are never accepted. */
export const jobsQuerySchema = z.object({
	department: optionalFilter,
	location: optionalFilter,
	employmentType: z
		.enum(["full-time", "part-time", "contract", "internship"])
		.optional(),
	remote: z.preprocess(
		(value) => (value === "true" ? true : value === "false" ? false : value),
		z.boolean().optional(),
	),
	search: optionalFilter,
	limit: z.coerce.number().int().min(1).max(100).default(12),
	offset: z.coerce.number().int().min(0).default(0),
});

import { jobSchema } from "./schemas";
import type {
	EmploymentType,
	Job,
	JobContentItem,
	JobData,
	JobsFilters,
	JobsPage,
	JobTaxonomies,
} from "./types";

/** Keep department labels in one URL segment when a host router decodes paths early. */
export function encodeJobDepartment(department: string): string {
	const encoded =
		department === "." || department === ".."
			? department.replaceAll(".", "%2E")
			: encodeURIComponent(department);
	return encoded.replaceAll("~", "%7E").replaceAll("%", "~");
}

/** Malformed department identifiers have no matching public department. */
export function decodeJobDepartment(identifier: string): string | undefined {
	if (identifier.includes("%")) return undefined;
	try {
		return decodeURIComponent(identifier.replaceAll("~", "%"));
	} catch {
		return undefined;
	}
}

/** A closing date includes its full UTC calendar day. */
export function isJobOpen(
	job: Pick<JobData, "status" | "closingDate">,
	now = new Date(),
): boolean {
	return (
		job.status === "published" &&
		(!job.closingDate || job.closingDate >= now.toISOString().slice(0, 10))
	);
}

/** Parse only declared job fields; unpublished, expired and invalid records stay private. */
export function toPublicJobs(
	items: readonly JobContentItem[],
	now = new Date(),
): Job[] {
	const jobs: Job[] = [];
	for (const item of items) {
		const parsed = jobSchema.safeParse(item.parsedData);
		if (!parsed.success || !isJobOpen(parsed.data, now)) continue;
		jobs.push({
			...parsed.data,
			id: item.id,
			slug: item.slug,
			createdAt: item.createdAt,
			updatedAt: item.updatedAt,
		});
	}
	return jobs;
}

/** Filter terms never reveal unpublished or expired postings. */
export function getJobTaxonomies(jobs: readonly Job[]): JobTaxonomies {
	const terms = (values: string[]) =>
		[...new Set(values)].sort((a, b) => a.localeCompare(b));
	return {
		departments: terms(jobs.map((job) => job.department)),
		locations: terms(jobs.map((job) => job.location)),
		employmentTypes: terms(
			jobs.map((job) => job.employmentType),
		) as EmploymentType[],
	};
}

/** Apply domain filters before pagination so totals and pages describe visible jobs. */
export function paginateJobs(
	jobs: readonly Job[],
	filters: JobsFilters = {},
): JobsPage {
	const text = (value?: string) => value?.trim().toLowerCase();
	const department = text(filters.department);
	const location = text(filters.location);
	const search = text(filters.search);
	const filtered = jobs.filter(
		(job) =>
			(!department || job.department.toLowerCase() === department) &&
			(!location || job.location.toLowerCase() === location) &&
			(!filters.employmentType ||
				job.employmentType === filters.employmentType) &&
			(filters.remote === undefined || job.remote === filters.remote) &&
			(!search ||
				[job.title, job.department, job.location, job.description].some(
					(value) => value.toLowerCase().includes(search),
				)),
	);
	const limit = filters.limit ?? 12;
	const offset = filters.offset ?? 0;
	return {
		items: filtered.slice(offset, offset + limit),
		total: filtered.length,
		limit,
		offset,
		taxonomies: getJobTaxonomies(jobs),
	};
}

import type { Job } from "./types";
import type { JobBoardOrganization } from "./client/types";

const employmentTypes = {
	"full-time": "FULL_TIME",
	"part-time": "PART_TIME",
	contract: "CONTRACTOR",
	internship: "INTERN",
} as const;

/** Build JobPosting data using only the job and the consumer's actual employer information. */
export function createJobPostingStructuredData(
	job: Job,
	options: { url?: string; organization?: JobBoardOrganization } = {},
) {
	return {
		"@context": "https://schema.org",
		"@type": "JobPosting",
		title: job.title,
		description: job.description,
		datePosted: job.createdAt,
		employmentType: employmentTypes[job.employmentType],
		identifier: { "@type": "PropertyValue", value: job.id },
		...(job.location
			? { jobLocation: { "@type": "Place", address: job.location } }
			: {}),
		...(job.remote ? { jobLocationType: "TELECOMMUTE" } : {}),
		...(job.closingDate
			? { validThrough: `${job.closingDate}T23:59:59Z` }
			: {}),
		...(options.url ? { url: options.url } : {}),
		...(options.organization
			? {
					hiringOrganization: {
						"@type": "Organization",
						...options.organization,
					},
				}
			: {}),
	};
}

/** Escape script-significant characters before inserting JSON-LD into an HTML script element. */
export function serializeJobPostingStructuredData(
	data: ReturnType<typeof createJobPostingStructuredData>,
) {
	return JSON.stringify(data)
		.replace(/</g, "\\u003c")
		.replace(/\u2028/g, "\\u2028")
		.replace(/\u2029/g, "\\u2029");
}

"use client";

import { lazy } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { encodeJobDepartment } from "../../../utils";
import { JobError, JobLoading, JobNotFound } from "../shared";

const JobList = lazy(() =>
	import("./job-list-page.internal").then((module) => ({
		default: module.JobListPage,
	})),
);

export function DepartmentPageComponent({
	department,
}: {
	department?: string;
}) {
	if (!department) return <JobNotFound />;
	return (
		<ComposedRoute
			path={`/jobs/department/${encodeJobDepartment(department)}`}
			PageComponent={JobList}
			ErrorComponent={JobError}
			LoadingComponent={JobLoading}
			NotFoundComponent={JobNotFound}
			onError={(error) => console.error("[btst/job-board]", error)}
			props={{ department }}
		/>
	);
}

"use client";

import { usePluginSiteNavigation, useStack } from "@btst/stack/context";
import { MarkdownContent } from "@/components/ui/markdown-content";
import { useRegisterPageAIContext } from "@btst/stack/page-context";
import { FormRenderer } from "@btst/plugin-form-builder/client/components";
import { Button } from "@/components/ui/button";
import {
	createJobPostingStructuredData,
	serializeJobPostingStructuredData,
} from "../../../structured-data";
import { encodeJobDepartment, isJobOpen } from "../../../utils";
import { JOB_BOARD_PLUGIN_ID } from "../../constants";
import {
	useJobBoardHydrated,
	useJobBoardLocalization,
	useSuspenseJob,
} from "@btst/plugin-job-board/client/hooks";
import type { JobBoardProviderConfig } from "../../types";
import { employmentLabel, JobNotFound, JobPage } from "../shared";

export function JobDetailPage({ slug }: { slug: string }) {
	const { data: job } = useSuspenseJob(slug);
	const copy = useJobBoardLocalization();
	const { Link, resolve } = usePluginSiteNavigation(JOB_BOARD_PLUGIN_ID);
	const { plugins, router } = useStack();
	const hydrated = useJobBoardHydrated();
	const open = !hydrated || isJobOpen(job);
	const provider = plugins?.[JOB_BOARD_PLUGIN_ID]?.config as
		| JobBoardProviderConfig
		| undefined;
	const site = plugins?.[JOB_BOARD_PLUGIN_ID]?.site;
	const url = site?.baseURL
		? `${site.baseURL}${resolve("jobs", encodeURIComponent(job.slug)).path}`
		: undefined;
	const applicationAvailable = !!(
		job.applicationFormSlug && plugins?.formBuilder
	);
	useRegisterPageAIContext(
		open
			? {
					routeName: "job-board-detail",
					pageDescription:
						`Job: ${job.title}\nDepartment: ${job.department}\nLocation: ${job.location}\nEmployment type: ${job.employmentType}\n\n${job.description}\n\nRequirements:\n${job.requirements}`.slice(
							0,
							16000,
						),
					suggestions: [
						"What are the requirements for this role?",
						"Summarize the responsibilities",
						"What should I include in my application?",
					],
				}
			: null,
	);
	if (!open) return <JobNotFound />;
	return (
		<JobPage>
			<script
				type="application/ld+json"
				dangerouslySetInnerHTML={{
					__html: serializeJobPostingStructuredData(
						createJobPostingStructuredData(job, {
							url,
							organization: provider?.organization,
						}),
					),
				}}
			/>
			<header className="flex min-w-0 max-w-4xl flex-col gap-5">
				<Link
					className="inline-flex min-h-11 items-center self-start text-sm underline underline-offset-4"
					href={resolve("jobs").href}
				>
					{copy.backToJobs}
				</Link>
				<Link
					className="inline-flex min-h-11 items-center self-start text-sm text-muted-foreground underline underline-offset-4"
					href={
						resolve("jobs", "department", encodeJobDepartment(job.department))
							.href
					}
				>
					{job.department}
				</Link>
				<h1 className="break-words text-4xl font-semibold leading-tight tracking-tight sm:text-5xl">
					{job.title}
				</h1>
			</header>
			<div className="grid min-w-0 gap-10 lg:grid-cols-[minmax(0,1fr)_18rem] lg:gap-14">
				<aside className="order-first flex min-w-0 flex-col gap-6 self-start rounded-lg border p-5 lg:order-last lg:p-6">
					<dl className="grid min-w-0 grid-cols-2 gap-5 text-sm sm:grid-cols-3 lg:grid-cols-1">
						<div className="flex min-w-0 flex-col gap-1">
							<dt className="text-muted-foreground">{copy.location}</dt>
							<dd className="break-words font-medium">{job.location}</dd>
						</div>
						<div className="flex flex-col gap-1">
							<dt className="text-muted-foreground">{copy.employmentType}</dt>
							<dd className="font-medium">
								{employmentLabel(job.employmentType, copy)}
							</dd>
						</div>
						<div className="flex flex-col gap-1">
							<dt className="text-muted-foreground">{copy.workplace}</dt>
							<dd className="font-medium">
								{job.remote ? copy.remote : copy.onSite}
							</dd>
						</div>
						{job.salary && (
							<div className="flex min-w-0 flex-col gap-1">
								<dt className="text-muted-foreground">{copy.salary}</dt>
								<dd className="break-words font-medium">{job.salary}</dd>
							</div>
						)}
						{job.closingDate && (
							<div className="flex flex-col gap-1">
								<dt className="text-muted-foreground">{copy.closingDate}</dt>
								<dd className="font-medium">
									<time dateTime={job.closingDate}>
										{new Intl.DateTimeFormat("en", {
											year: "numeric",
											month: "long",
											day: "numeric",
											timeZone: "UTC",
										}).format(new Date(`${job.closingDate}T00:00:00Z`))}
									</time>
								</dd>
							</div>
						)}
					</dl>
					{applicationAvailable ? (
						<Button className="min-h-11" asChild>
							<a href="#apply">{copy.apply}</a>
						</Button>
					) : (
						<p className="text-sm text-muted-foreground">
							{copy.applicationsUnavailable}
						</p>
					)}
				</aside>
				<article className="order-last flex min-w-0 max-w-prose flex-col gap-10 lg:order-first">
					<section className="flex min-w-0 flex-col gap-4">
						<h2 className="text-2xl font-semibold">{copy.aboutRole}</h2>
						<MarkdownContent
							markdown={job.description}
							LinkComponent={router?.Link}
							ImageComponent={router?.Image}
						/>
					</section>
					{job.requirements && (
						<section className="flex min-w-0 flex-col gap-4">
							<h2 className="text-2xl font-semibold">{copy.requirements}</h2>
							<MarkdownContent
								markdown={job.requirements}
								LinkComponent={router?.Link}
								ImageComponent={router?.Image}
							/>
						</section>
					)}
				</article>
			</div>
			{applicationAvailable && (
				<section
					id="apply"
					aria-labelledby="job-board-application-heading"
					className="flex min-w-0 max-w-prose scroll-mt-8 flex-col gap-5 rounded-lg border p-5 sm:p-7"
				>
					<h2
						id="job-board-application-heading"
						className="text-2xl font-semibold"
					>
						{copy.application}
					</h2>
					<p className="text-muted-foreground">{copy.applicationDescription}</p>
					<FormRenderer
						key={`${job.id}:${job.applicationFormSlug}`}
						slug={job.applicationFormSlug!}
					/>
				</section>
			)}
		</JobPage>
	);
}

"use client";

import { lazy } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { JobError, JobLoading, JobNotFound } from "../shared";

const JobDetail = lazy(() =>
	import("./job-detail-page.internal").then((module) => ({
		default: module.JobDetailPage,
	})),
);

export function JobDetailPageComponent({ slug }: { slug: string }) {
	return (
		<ComposedRoute
			path={`/jobs/${slug}`}
			PageComponent={JobDetail}
			ErrorComponent={JobError}
			LoadingComponent={JobLoading}
			NotFoundComponent={JobNotFound}
			onError={(error) => console.error("[btst/job-board]", error)}
			props={{ slug }}
		/>
	);
}

"use client";

import { useState } from "react";
import { usePluginSiteNavigation } from "@btst/stack/context";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import type { EmploymentType, Job, JobsFilters } from "../../../types";
import { isJobOpen } from "../../../utils";
import { JOB_BOARD_PLUGIN_ID } from "../../constants";
import {
	useJobBoardHydrated,
	useJobBoardLocalization,
	useSuspenseJobs,
} from "@btst/plugin-job-board/client/hooks";
import { employmentLabel, JobPage, JobsEmpty, jobSelectClass } from "../shared";

function JobRow({ job }: { job: Job }) {
	const copy = useJobBoardLocalization();
	const { Link, resolve } = usePluginSiteNavigation(JOB_BOARD_PLUGIN_ID);
	return (
		<li>
			<Link
				aria-label={job.title}
				href={resolve("jobs", encodeURIComponent(job.slug)).href}
				className="group grid min-w-0 gap-4 py-6 transition-colors hover:bg-muted/40 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring motion-reduce:transition-none sm:grid-cols-[minmax(0,1.6fr)_minmax(0,1fr)_auto] sm:items-center sm:gap-6 sm:py-7"
			>
				<div className="flex min-w-0 flex-col gap-2">
					<h2 className="break-words text-xl font-semibold leading-snug group-hover:underline group-hover:underline-offset-4 sm:text-2xl">
						{job.title}
					</h2>
					<span className="break-words text-sm text-muted-foreground">
						{job.department}
					</span>
				</div>
				<div className="flex min-w-0 flex-col gap-1 text-sm">
					<span className="break-words">{job.location}</span>
					{job.remote && (
						<span className="text-muted-foreground">{copy.remote}</span>
					)}
				</div>
				<div className="flex items-center justify-between gap-4 text-sm sm:flex-col sm:items-end sm:gap-2">
					<span>{employmentLabel(job.employmentType, copy)}</span>
					<span className="font-medium underline underline-offset-4">
						{copy.viewRole}
					</span>
				</div>
			</Link>
		</li>
	);
}

export function JobListPage({ department }: { department?: string }) {
	const copy = useJobBoardLocalization();
	const { Link, resolve } = usePluginSiteNavigation(JOB_BOARD_PLUGIN_ID);
	const [state, setFilterState] = useState({
		department: "",
		location: "",
		employmentType: "",
		remote: false,
	});
	const setState = (patch: Partial<typeof state>) =>
		setFilterState((current) => ({ ...current, ...patch }));
	const employmentType = [
		"full-time",
		"part-time",
		"contract",
		"internship",
	].includes(state.employmentType)
		? (state.employmentType as EmploymentType)
		: undefined;
	const filters: JobsFilters = {
		department: department || state.department || undefined,
		location: state.location || undefined,
		employmentType,
		remote: state.remote || undefined,
	};
	const { data, fetchNextPage, hasNextPage, isFetchingNextPage } =
		useSuspenseJobs(filters);
	const hydrated = useJobBoardHydrated();
	const jobs = data.pages
		.flatMap((page) => page.items)
		.filter((job) => !hydrated || isJobOpen(job));
	const firstPage = data.pages[0];
	const taxonomies = firstPage?.taxonomies;
	const filtered = !!(
		filters.department ||
		filters.location ||
		filters.employmentType ||
		filters.remote
	);
	const canClear = !!(
		(!department && state.department) ||
		state.location ||
		state.employmentType ||
		state.remote
	);
	return (
		<JobPage>
			<header className="flex max-w-3xl flex-col gap-4">
				{department && (
					<Link
						className="inline-flex min-h-11 items-center self-start text-sm underline underline-offset-4"
						href={resolve("jobs").href}
					>
						{copy.backToJobs}
					</Link>
				)}
				<h1 className="break-words text-4xl font-semibold leading-tight tracking-tight sm:text-5xl">
					{department
						? copy.departmentTitle.replace("{department}", department)
						: copy.title}
				</h1>
				<p className="max-w-2xl text-lg leading-relaxed text-muted-foreground">
					{copy.intro}
				</p>
			</header>
			<fieldset className="grid min-w-0 gap-4 rounded-lg border bg-muted/20 p-4 sm:grid-cols-2 lg:grid-cols-4 lg:p-5">
				<legend className="sr-only">{copy.title}</legend>
				{!department && (
					<div className="flex min-w-0 flex-col gap-2">
						<Label htmlFor="job-board-department">{copy.department}</Label>
						<select
							id="job-board-department"
							className={jobSelectClass}
							value={state.department}
							onChange={(event) => setState({ department: event.target.value })}
						>
							<option value="">{copy.allDepartments}</option>
							{taxonomies?.departments.map((value) => (
								<option key={value} value={value}>
									{value}
								</option>
							))}
						</select>
					</div>
				)}
				<div className="flex min-w-0 flex-col gap-2">
					<Label htmlFor="job-board-location">{copy.location}</Label>
					<select
						id="job-board-location"
						className={jobSelectClass}
						value={state.location}
						onChange={(event) => setState({ location: event.target.value })}
					>
						<option value="">{copy.allLocations}</option>
						{taxonomies?.locations.map((value) => (
							<option key={value} value={value}>
								{value}
							</option>
						))}
					</select>
				</div>
				<div className="flex min-w-0 flex-col gap-2">
					<Label htmlFor="job-board-type">{copy.employmentType}</Label>
					<select
						id="job-board-type"
						className={jobSelectClass}
						value={state.employmentType}
						onChange={(event) =>
							setState({ employmentType: event.target.value })
						}
					>
						<option value="">{copy.allEmploymentTypes}</option>
						{taxonomies?.employmentTypes.map((value) => (
							<option key={value} value={value}>
								{employmentLabel(value, copy)}
							</option>
						))}
					</select>
				</div>
				<label className="flex min-h-11 items-center gap-3 self-end text-sm">
					<input
						className="size-5 accent-primary"
						type="checkbox"
						checked={state.remote}
						onChange={(event) => setState({ remote: event.target.checked })}
					/>
					{copy.remoteOnly}
				</label>
			</fieldset>
			<section aria-label={copy.title} className="flex min-w-0 flex-col gap-5">
				<div className="flex flex-wrap items-center justify-between gap-3">
					<p role="status" className="text-sm text-muted-foreground">
						{copy.openRoles.replace("{count}", String(firstPage?.total ?? 0))}
					</p>
					{canClear && (
						<Button
							className="min-h-11"
							variant="ghost"
							onClick={() =>
								setState({
									department: "",
									location: "",
									employmentType: "",
									remote: false,
								})
							}
						>
